                $years += $intValue;

                break;

            case 'quarter':
            case 'quarters':
                $months += $intValue * CarbonInterface::MONTHS_PER_QUARTER;

                break;

            case 'month':
            case 'months':
            case 'mo':
            case 'mos':
                $months += $intValue;

                break;

            case 'week':
            case 'weeks':
            case 'w':
                $weeks += $intValue;

                if ($fraction) {
                    $parts[] = [null, $fraction * static::getDaysPerWeek(), 'd'];
                }

                break;

            case 'day':
            case 'days':
            case 'd':
                $days += $intValue;

                if ($fraction) {
                    $parts[] = [null, $fraction * static::getHoursPerDay(), 'h'];
                }

                break;

            case 'hour':
            case 'hours':
            case 'h':
                $hours += $intValue;

                if ($fraction) {
                    $parts[] = [null, $fraction * static::getMinutesPerHour(), 'm'];
                }

                break;

            case 'minute':
            case 'minutes':
            case 'm':
                $minutes += $intValue;

                if ($fraction) {
                    $parts[] = [null, $fraction * static::getSecondsPerMinute(), 's'];
                }

                break;

            case 'second':
            case 'seconds':
            case 's':
                $seconds += $intValue;

                if ($fraction) {
